/* Proposals are stored independently from financial records. */
let proposalData={company:null,catalog:[],proposals:[],loading:false,error:''},proposalTab='documents',proposalDraft=null,proposalRecord=null,proposalRequest=0,proposalShowArchived=false;
const proposalM=globalThis.ProposalModel;
function proposalManager(){return canManage('Propostas');}
async function proposalApi(payload){if(!cloudSession)throw Error('Entre novamente.');const send=()=>fetch(CLOUD_URL+'/functions/v1/proposals-api',{method:'POST',headers:{apikey:CLOUD_KEY,Authorization:'Bearer '+cloudSession.access_token,'Content-Type':'application/json'},body:JSON.stringify(payload)});let res=await send();if(res.status===401){await api('load');res=await send();}const data=await res.json();if(!res.ok||data.error)throw Error(data.error||'Não foi possível salvar.');return data;}
function proposalCompany(){return company!=='all'?company:allowed().length===1?allowed()[0].id:null;}
async function fetchProposals(force=false){const c=proposalCompany();if(!c||(!force&&proposalData.company===c))return;const request=++proposalRequest;proposalData={company:c,catalog:[],proposals:[],loading:true,error:''};try{const data=await proposalApi({action:'list',company:c});if(request!==proposalRequest)return;proposalData={company:c,...data,loading:false,error:''};}catch(e){if(request!==proposalRequest)return;proposalData.loading=false;proposalData.error=e.message;}if(page==='Propostas')render();}
function renderProposals(){const c=proposalCompany();if(!c)return title('Propostas comerciais','Crie propostas com a identidade e os preços de cada empresa.')+empty('Selecione uma empresa','Use o seletor à esquerda para acessar o catálogo e as propostas da empresa.');if(proposalData.company!==c){queueMicrotask(()=>fetchProposals());return title('Propostas comerciais','Preparando catálogo…');}const d=proposalData;if(d.loading)return title('Propostas comerciais','Carregando propostas e tabela comercial…');if(d.error)return title('Propostas comerciais','Não foi possível carregar os dados.')+`<div class="notice">${esc(d.error)}</div>${btn('Tentar novamente','fetchProposals(true)')}`;const active=d.catalog.filter(x=>x.kind!=='brand'&&!x.data.archived);const tabs=`<div class="proposal-tabs" role="tablist">${[['documents','Propostas'],...(proposalManager()?[['catalog','Planos e módulos'],['brand','Identidade e conteúdo']]:[])].map(([id,label])=>`<button role="tab" aria-selected="${proposalTab===id}" class="btn ${proposalTab===id?'':'secondary'}" onclick="proposalTab='${id}';render()">${label}</button>`).join('')}</div>`;let content='';if(proposalTab==='documents'||!proposalManager()){content=metric([['Propostas',d.proposals.filter(x=>x.data.status!=='archived').length,'Neste acesso · até 200 recentes'],['Enviadas',d.proposals.filter(x=>x.data.status==='sent').length,'Status informado pela equipe'],['Aceitas',d.proposals.filter(x=>x.data.status==='accepted').length,'Status informado pela equipe'],['Itens no catálogo',active.length,'Planos e módulos disponíveis']])+`${btn(proposalShowArchived?'Ocultar arquivadas':'Mostrar arquivadas','proposalShowArchived=!proposalShowArchived;render()',true)}<div class="proposal-list">${d.proposals.filter(x=>proposalShowArchived||x.data.status!=='archived').map(x=>`<article class="panel proposal-card"><div><span class="eyebrow">${esc(proposalCode(x))} · ${compactDate(x.data.issued)}</span><h2>${esc(x.data.client)}</h2><p>${esc(x.data.title)}</p><span class="pill ${x.data.status==='draft'?'amber':''}">${esc(proposalStatus(x.data.status))}</span> <span class="small">Válida até ${compactDate(x.data.validUntil)}</span></div><div class="catalog-actions">${btn('Abrir',`editProposal('${actionId(x.id)}')`,true)}${btn('Duplicar',`duplicateProposal('${actionId(x.id)}')`,true)}${btn('PDF',`viewProposal('${actionId(x.id)}')`)}</div></article>`).join('')||empty('Sua próxima proposta começa aqui','Escolha os planos, personalize as condições e confira o documento antes de exportar.')}</div>`;}else if(proposalTab==='catalog'){content=`<div class="proposal-tools">${btn('+ Plano',"editProposalCatalog(null,'plan')")}${btn('+ Módulo',"editProposalCatalog(null,'module')",true)}${c==='quantis'?btn('Carregar referência Quantis','seedQuantisCatalog()',true):''}</div><div class="proposal-catalog">${d.catalog.filter(x=>x.kind!=='brand').map(x=>`<article class="panel"><span class="eyebrow">${x.kind==='plan'?'Plano':'Módulo'} ${x.data.archived?'· Arquivado':''}</span><h2>${esc(x.data.name)}</h2><p>${esc(x.data.description)}</p><div class="proposal-price">${money(x.data.price)}<small> / ${x.data.cadence==='monthly'?'mês':'venda'}</small></div><p class="small">Implantação: ${x.data.setup===null?'Definir na proposta':money(x.data.setup)}</p><ul>${proposalM.lines(x.data.features).map(t=>`<li>${esc(t)}</li>`).join('')}</ul>${btn('Editar',`editProposalCatalog('${actionId(x.id)}')`,true)}</article>`).join('')||empty('Cadastre sua tabela comercial','Planos e módulos são exclusivos desta empresa.')}</div>`;}else content=`<section class="panel"><h2>A identidade da sua empresa em cada proposta</h2><p>Configure marca, imagens, argumentos, recursos, implantação e condições padrão. Cada nova proposta guarda uma cópia deste conteúdo.</p><p>Use imagens HTTPS da própria empresa. Não inclua documentos privados como imagem pública.</p>${btn('Personalizar modelo','editProposalBrand()')}</section>`;return title('Propostas comerciais','Do catálogo à proposta. Uma apresentação à altura da sua empresa.',btn('+ Nova proposta','editProposal()'))+tabs+content;}
function proposalStatus(s){return {draft:'Rascunho',sent:'Enviada',accepted:'Aceita',declined:'Recusada',archived:'Arquivada'}[s]||s;}
function proposalCode(r){return 'PROP-'+r.id.slice(0,8).toUpperCase();}
function defaultProposalBrand(){const quantis=proposalCompany()==='quantis';return {name:companyName(proposalCompany()),color:'#15bfc7',logo:'',cover:quantis?'https://quantisgrowth.github.io/comissions/assets/quantis-cover.jpg':'',headline:quantis?'Gestão operacional e financeira para empresas que vivem da frota':'Uma solução pensada para a sua operação',subtitle:quantis?'Da abertura da ordem de serviço ao custo por veículo, com a informação no mesmo fluxo.':'Tecnologia, acompanhamento e condições alinhadas ao seu negócio.',email:quantis?'comercial@quantislift.com.br':'',phone:'',website:quantis?'quantislift.com.br':'',benefits:quantis?'Menos retrabalho | OS, agenda e responsável no mesmo registro.\nMais controle | Pendências operacionais e financeiras no mesmo fluxo.\nResultado por veículo | Entenda onde os custos e o faturamento se formam.':'Processos organizados | Mais clareza para a rotina da equipe.\nInformação acessível | Decisões apoiadas no histórico da operação.',resources:quantis?'Ordens de serviço | Agenda, abertura, execução, assinatura e histórico.\nFinanceiro | Contas a receber, pagamentos, despesas e investimentos.\nFrota | Veículos, leituras, manutenção, combustível e movimentações.\nFiscal | Configuração e rascunhos de NFS-e, conforme o módulo contratado.\nClientes e equipe | Cadastros, perfis e permissões.\nRelatórios | Visões gerenciais e acompanhamento do resultado.':'Escopo personalizado | Recursos conforme os itens desta proposta.',implementation:'Diagnóstico | Alinhamento de processos, usuários e prioridades.\nConfiguração | Preparação do ambiente e dos dados iniciais.\nTreinamento | Orientação da equipe nos principais fluxos.\nEntrada em operação | Acompanhamento inicial e ajustes de uso.',terms:'O início da cobrança e o vencimento serão definidos na contratação.\nIntegrações, migrações, treinamentos adicionais e personalizações somente quando expressamente incluídos.\nO cronograma depende do escopo, dos dados e da disponibilidade da equipe do cliente.\nCondições de fidelidade, aviso prévio e eventual multa serão detalhadas no contrato.',closing:'Escolha a condição comercial e fale com o responsável pela proposta para confirmar o escopo e iniciar a contratação.'};}
function currentProposalBrand(){return structuredClone(proposalData.catalog.find(x=>x.kind==='brand')?.data||defaultProposalBrand());}
function proposalDialog(html){let m=document.getElementById('proposalModal');if(!m){m=document.createElement('dialog');m.id='proposalModal';document.body.appendChild(m);}m.innerHTML=html;if(!m.open)m.showModal();return m;}
function proposalClose(){document.getElementById('proposalModal')?.close();}
function proposalText(name,label,value,rows=4){return `<div class="field"><label for="p_${name}">${label}</label><textarea id="p_${name}" name="${name}" rows="${rows}">${esc(value||'')}</textarea></div>`;}
function proposalField(name,label,value,type='text',attrs=''){return field(name,label,value??'',type,attrs);}
function proposalFeedback(e){const el=document.getElementById('proposalError');if(el){el.textContent=e.message||String(e);el.hidden=false;}else toast(e.message||String(e));}
function catalogFormData(f,kind){return {kind,name:f.get('name'),description:f.get('description'),price:Number(f.get('price')),setup:f.get('setup')===''?null:Number(f.get('setup')),cadence:f.get('cadence'),features:f.get('features'),usage:f.get('usage'),unit:f.get('unit'),archived:f.has('archived')};}
function editProposalCatalog(id,kind){if(!proposalManager())return;const row=proposalData.catalog.find(x=>x.id===id),d=row?.data||{name:'',price:0,setup:null,cadence:'monthly',features:'',description:'',usage:'',unit:'unidade'};kind=row?.kind||kind;const m=proposalDialog(`<form id="proposalCatalogForm"><div class="proposal-modal-head"><div><span class="eyebrow">Tabela comercial · ${esc(companyName(proposalCompany()))}</span><h2>${id?'Editar':'Novo'} ${kind==='plan'?'plano':'módulo'}</h2></div><button type="button" class="icon-action" aria-label="Fechar" onclick="proposalClose()">×</button></div><div class="formgrid">${field('name','Nome',d.name,'text','required maxlength="100"')}${select('cadence','Natureza da cobrança',[['monthly','Mensal recorrente'],['once','Venda pontual']],d.cadence)}${field('price','Preço base (R$)',d.price,'number','required min="0" step="0.01"')}${field('setup','Implantação base (R$) · vazio = negociar',d.setup??'','number','min="0" step="0.01"')}${field('unit','Unidade (ex.: usuário, pacote)',d.unit)}${field('description','Descrição',d.description)}</div>${proposalText('features','Recursos e limites · um por linha',d.features)}${proposalText('usage','Uso, excedentes e observações',d.usage,2)}<label class="proposal-check"><input type="checkbox" name="archived" ${d.archived?'checked':''}> Arquivar item (preserva propostas anteriores)</label><p id="proposalError" role="alert" hidden></p><div class="actions">${btn('Cancelar','proposalClose()',true)}<button class="btn" type="submit">Salvar item</button></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const data=proposalM.item(catalogFormData(new FormData(e.target),kind));await proposalApi({action:'catalog-save',company:proposalCompany(),id,version:row?.version,kind,data});proposalClose();await fetchProposals(true);}catch(err){proposalFeedback(err);}finally{button.disabled=false;}};}
function editProposalBrand(){if(!proposalManager())return;const row=proposalData.catalog.find(x=>x.kind==='brand'),d=currentProposalBrand();const m=proposalDialog(`<form><div class="proposal-modal-head"><div><span class="eyebrow">Modelo da empresa</span><h2>Identidade e conteúdo</h2></div>${btn('Fechar','proposalClose()',true)}</div><div class="formgrid">${field('name','Nome da marca',d.name,'text','required')}${field('color','Cor de destaque',d.color,'color')}${field('logo','URL do logotipo (HTTPS)',d.logo,'url')}${field('cover','URL da imagem de capa (HTTPS)',d.cover,'url')}${field('headline','Título de capa',d.headline)}${field('subtitle','Subtítulo',d.subtitle)}${field('email','E-mail comercial',d.email,'email')}${field('phone','Telefone / WhatsApp',d.phone)}${field('website','Site',d.website)}</div><p class="small">Nos blocos abaixo, use uma linha por tópico e separe o título da descrição com |.</p>${proposalText('benefits','Benefícios',d.benefits)}${proposalText('resources','Recursos da solução',d.resources)}${proposalText('implementation','Etapas da implantação',d.implementation)}${proposalText('terms','Condições e limites do escopo',d.terms)}${proposalText('closing','Próximo passo',d.closing,2)}<p id="proposalError" role="alert" hidden></p><div class="actions"><button class="btn" type="submit">Salvar modelo</button></div></form>`);m.querySelector('form').onsubmit=async e=>{e.preventDefault();e.submitter.disabled=true;try{const data=proposalM.brand(Object.fromEntries(new FormData(e.target)));await proposalApi({action:'catalog-save',company:proposalCompany(),id:row?.id,version:row?.version,kind:'brand',data});proposalClose();await fetchProposals(true);}catch(err){proposalFeedback(err);e.submitter.disabled=false;}};}
async function seedQuantisCatalog(){if(!proposalManager()||proposalCompany()!=='quantis')return;const templates=[{kind:'plan',name:'Lift Start',price:397,features:'Até 2 usuários\nAté 5 veículos ou máquinas\nMotoristas ilimitados\nRecursos essenciais',description:'Para operações pequenas e em início de organização.'},{kind:'plan',name:'Lift Pro',price:697,features:'Até 5 usuários\nAté 20 veículos ou máquinas\nMotoristas ilimitados\nRecursos essenciais',description:'Para equipes em crescimento e com mais ativos.'},{kind:'plan',name:'Lift Unlimited',price:1297,features:'Usuários ilimitados*\nVeículos e máquinas ilimitados*\nMotoristas ilimitados',usage:'* Sujeito à política de uso adequado, a ser detalhada na contratação.',description:'Para operações consolidadas.'},{kind:'module',name:'Usuário adicional',price:19.9,unit:'usuário',features:'Acesso de um usuário adicional'},{kind:'module',name:'Módulo NFS-e',price:149,features:'Módulo fiscal NFS-e'}];try{for(const t of templates){if(proposalData.catalog.some(x=>x.data.name===t.name))continue;const result=await proposalApi({action:'catalog-save',company:'quantis',kind:t.kind,data:proposalM.item({cadence:'monthly',setup:null,...t})});proposalData.catalog.push(result.record);}await fetchProposals(true);toast('Tabela de referência carregada. Defina a implantação e revise os escopos.');}catch(e){proposalFeedback(e);await fetchProposals(true);}}
function proposalNewOption(name='Condição principal'){return {name,items:[],setup:0,setupConfirmed:false,parts:1,loyalty:0,payment:'Pix, boleto ou cartão de crédito',notes:''};}
function editProposal(id){if(!proposalData.company)return;proposalRecord=proposalData.proposals.find(x=>x.id===id)||null;const today=localToday(),expiry=new Date(today+'T12:00:00Z');expiry.setUTCDate(expiry.getUTCDate()+15);proposalDraft=structuredClone(proposalRecord?.data||{client:'',contact:'',email:'',phone:'',title:'Proposta comercial',issued:today,validUntil:expiry.toISOString().slice(0,10),status:'draft',diagnosis:'',brand:currentProposalBrand(),seller:user().name,sellerEmail:user().email||'',options:[proposalNewOption()]});renderProposalEditor();}
function renderProposalEditor(){const d=proposalDraft;const catalog=proposalData.catalog.filter(x=>x.kind!=='brand'&&!x.data.archived);const input=(name,label,value,type='text',attrs='')=>field(name,label,value,type,attrs);const m=proposalDialog(`<form id="proposalEditor"><div class="proposal-modal-head"><div><span class="eyebrow">${esc(companyName(proposalCompany()))} · ${proposalRecord?esc(proposalCode(proposalRecord)):'Nova proposta'}</span><h2>Uma proposta feita para o seu cliente</h2></div>${btn('Fechar','proposalClose()',true)}</div><div class="proposal-editor-grid"><div class="proposal-editor-fields"><h3>01 · Cliente e proposta</h3><div class="formgrid">${input('client','Empresa cliente',d.client,'text','required maxlength="160"')}${input('contact','Nome do contato',d.contact)}${input('email','E-mail do contato',d.email,'email')}${input('phone','Telefone',d.phone)}${input('issued','Emissão',d.issued,'date','required')}${input('validUntil','Validade',d.validUntil,'date','required')}${input('title','Título',d.title)}${select('status','Status (registro manual)',Object.entries({draft:'Rascunho',sent:'Enviada',accepted:'Aceita',declined:'Recusada',archived:'Arquivada'}),d.status)}${input('seller','Responsável comercial',d.seller)}${input('sellerEmail','E-mail do responsável',d.sellerEmail,'email')}</div>${proposalText('diagnosis','Necessidades identificadas na conversa',d.diagnosis,3)}<h3>02 · Condições comerciais</h3><p class="small">O catálogo sugere os preços. Valores, recursos e limites permanecem negociáveis nesta proposta.</p>${d.options.map((o,n)=>`<section class="proposal-option"><div class="proposal-option-head"><h3>Opção ${n+1}</h3>${d.options.length>1?btn('Remover',`removeProposalOption(${n})`,true):''}</div>${input('o'+n+'name','Nome da condição',o.name,'text','required')}<div class="proposal-add-item"><select id="addCatalog${n}" aria-label="Plano ou módulo para opção ${n+1}"><option value="">Escolha um plano ou módulo…</option>${catalog.map(c=>`<option value="${esc(c.id)}">${esc(c.data.name)} · ${money(c.data.price)}</option>`).join('')}</select>${btn('Adicionar',`addProposalItem(${n})`,true)}</div>${o.items.map((i,j)=>`<div class="proposal-line"><div class="proposal-option-head"><strong>${esc(i.name)}</strong>${btn('Retirar',`removeProposalItem(${n},${j})`,true)}</div><div class="formgrid">${input(`i${n}_${j}_name`,'Nome no documento',i.name)}${select(`i${n}_${j}_cadence`,'Cobrança',[['monthly','Mensal'],['once','Pontual']],i.cadence)}${input(`i${n}_${j}_quantity`,'Quantidade',i.quantity,'number','min="1" max="10000" step="1" required')}${input(`i${n}_${j}_price`,'Preço unitário normal (R$)',i.price,'number','min="0" step="0.01" required')}${input(`i${n}_${j}_promoPrice`,'Preço unitário promocional (R$)',i.promoPrice,'number','min="0" step="0.01" required')}${input(`i${n}_${j}_promoMonths`,'Meses de promoção · 0 = sem desconto',i.promoMonths,'number','min="0" max="60" step="1" required')}</div>${proposalText(`i${n}_${j}_features`,'Recursos e limites incluídos',i.features,3)}${proposalText(`i${n}_${j}_usage`,'Uso e excedentes',i.usage,2)}</div>`).join('')||'<p class="notice">Adicione pelo menos um plano ou módulo.</p>'}<div class="formgrid">${input('o'+n+'setup','Implantação total negociada (R$)',o.setup,'number','min="0" step="0.01" required')}${input('o'+n+'parts','Parcelas da implantação',o.parts,'number','min="1" max="60" required')}${input('o'+n+'loyalty','Fidelidade em meses · 0 = sem',o.loyalty,'number','min="0" max="120" required')}${input('o'+n+'payment','Meios de pagamento',o.payment)}</div><label class="proposal-check"><input type="checkbox" name="o${n}setupConfirmed" ${o.setupConfirmed?'checked':''} required> Confirmei o valor da implantação, inclusive quando isenta.</label>${proposalText('o'+n+'notes','Condições específicas desta opção',o.notes,2)}<div class="proposal-subtotal">Total mensal inicial <strong>${money(proposalM.totals(o).monthly)}</strong></div></section>`).join('')}<div class="proposal-tools">${d.options.length<3?btn('+ Comparar outra condição','addProposalOption()',true):''}</div><details><summary>03 · Personalizar conteúdo desta proposta</summary><p class="small">Estas alterações afetam somente este documento.</p>${input('brandName','Nome da marca',d.brand.name)}${input('brandHeadline','Título da capa',d.brand.headline)}${input('brandSubtitle','Subtítulo',d.brand.subtitle)}${proposalText('brandBenefits','Benefícios',d.brand.benefits)}${proposalText('brandResources','Recursos',d.brand.resources)}${proposalText('brandImplementation','Implantação',d.brand.implementation)}${proposalText('brandTerms','Condições gerais',d.brand.terms)}${proposalText('brandClosing','Próximo passo',d.brand.closing)}</details></div><div class="proposal-preview-pane"><div class="proposal-preview-label">PRÉVIA DO DOCUMENTO · A4 PAISAGEM</div><iframe id="proposalPreview" title="Prévia da proposta" sandbox="allow-same-origin allow-modals"></iframe></div></div><div class="proposal-modal-footer"><p id="proposalError" role="alert" hidden></p><span class="small">Salve para manter a proposta disponível para a equipe autorizada.</span><div class="catalog-actions">${btn('Ver documento','previewProposalDraft()',true)}<button type="submit" class="btn">Salvar proposta</button></div></div></form>`);const form=m.querySelector('form');let timer;form.oninput=form.onchange=()=>{readProposalEditor();clearTimeout(timer);timer=setTimeout(updateProposalPreview,250);};form.onsubmit=saveProposalEditor;updateProposalPreview();}
function readProposalEditor(){const form=document.getElementById('proposalEditor');if(!form)return;const f=new FormData(form),d=proposalDraft;for(const key of ['client','contact','email','phone','title','issued','validUntil','status','seller','sellerEmail','diagnosis'])d[key]=String(f.get(key)||'');for(const [key,fieldName] of Object.entries({name:'brandName',headline:'brandHeadline',subtitle:'brandSubtitle',benefits:'brandBenefits',resources:'brandResources',implementation:'brandImplementation',terms:'brandTerms',closing:'brandClosing'}))d.brand[key]=String(f.get(fieldName)||'');d.options.forEach((o,n)=>{o.setupConfirmed=f.has('o'+n+'setupConfirmed');for(const key of ['name','payment','notes'])o[key]=String(f.get('o'+n+key)||'');for(const key of ['setup','parts','loyalty'])o[key]=Number(f.get('o'+n+key));o.items.forEach((i,j)=>{for(const key of ['name','cadence','features','usage'])i[key]=String(f.get(`i${n}_${j}_${key}`)||'');for(const key of ['quantity','price','promoPrice','promoMonths'])i[key]=Number(f.get(`i${n}_${j}_${key}`));});});}
function addProposalItem(n){const id=document.getElementById('addCatalog'+n).value,c=proposalData.catalog.find(x=>x.id===id);if(!c)return;readProposalEditor();if(proposalDraft.options[n].items.length>=20)return toast('Limite de 20 itens por condição.');const i=c.data;proposalDraft.options[n].items.push({catalogId:c.id,name:i.name,kind:c.kind,cadence:i.cadence,quantity:1,price:i.price,promoPrice:i.price,promoMonths:0,features:i.features,usage:i.usage});proposalDraft.options[n].setupConfirmed=false;if(i.setup!==null)proposalDraft.options[n].setup+=i.setup;else toast('Defina o valor negociado da implantação nesta condição.');renderProposalEditor();}
function removeProposalItem(n,j){readProposalEditor();proposalDraft.options[n].items.splice(j,1);renderProposalEditor();}
function addProposalOption(){readProposalEditor();if(proposalDraft.options.length>=3)return;const o=structuredClone(proposalDraft.options[0]);o.name='Condição alternativa';o.setupConfirmed=false;proposalDraft.options.push(o);renderProposalEditor();}
function removeProposalOption(n){readProposalEditor();proposalDraft.options.splice(n,1);renderProposalEditor();}
function updateProposalPreview(){const frame=document.getElementById('proposalPreview');if(frame)try{frame.srcdoc=proposalDocument(proposalDraft,proposalRecord?proposalCode(proposalRecord):'PRÉVIA',Math.min(1,(frame.clientWidth-24)/1047));}catch(e){proposalFeedback(e);}}
async function saveProposalEditor(e){e.preventDefault();readProposalEditor();const b=e.submitter;b.disabled=true;try{const data=proposalM.proposal(proposalDraft);const result=await proposalApi({action:'save',company:proposalCompany(),id:proposalRecord?.id,version:proposalRecord?.version,data});proposalRecord=result.record;proposalDraft=structuredClone(result.record.data);await fetchProposals(true);renderProposalEditor();toast('Proposta salva. Você já pode visualizar e gerar o PDF.');}catch(error){proposalFeedback(error);}finally{b.disabled=false;}}
async function duplicateProposal(id){try{const result=await proposalApi({action:'duplicate',company:proposalCompany(),id});await fetchProposals(true);editProposal(result.record.id);}catch(e){proposalFeedback(e);}}
function viewProposal(id){const row=proposalData.proposals.find(x=>x.id===id);if(!row)return;proposalDraft=structuredClone(row.data);proposalRecord=row;showProposalDocument(false);}
function previewProposalDraft(){readProposalEditor();try{proposalM.proposal(proposalDraft);showProposalDocument(true);}catch(e){proposalFeedback(e);}}
function showProposalDocument(back){const m=proposalDialog(`<div class="proposal-modal-head"><div><span class="eyebrow">${proposalRecord?esc(proposalCode(proposalRecord)):'Prévia não salva'}</span><h2>${esc(proposalDraft.client)}</h2></div><div class="catalog-actions">${back?btn('Voltar à edição','renderProposalEditor()',true):btn('Editar',`editProposal('${actionId(proposalRecord.id)}')`,true)}${btn('Gerar PDF','printProposalDocument()')}${btn('Fechar','proposalClose()',true)}</div></div><p class="small">Na janela de impressão, escolha “Salvar como PDF”. O documento já está preparado em paisagem.</p><iframe id="proposalFullPreview" title="Documento da proposta" sandbox="allow-same-origin allow-modals"></iframe>`);const frame=m.querySelector('iframe');frame.srcdoc=proposalDocument(proposalDraft,proposalRecord?proposalCode(proposalRecord):'PRÉVIA',Math.min(1,(frame.clientWidth-24)/1047));}
async function printProposalDocument(){const frame=document.getElementById('proposalFullPreview');if(!frame)return;try{await Promise.all([...frame.contentDocument.images].map(img=>img.complete?Promise.resolve():new Promise(resolve=>{img.onload=img.onerror=resolve;setTimeout(resolve,3000);})));frame.contentWindow.focus();frame.contentWindow.print();}catch(e){toast('Abra a prévia novamente para gerar o PDF.');}}
const proposalBaseRender=render;render=function(){proposalBaseRender();if(page==='Propostas'&&accessibleModules().includes('Propostas'))document.getElementById('app').innerHTML=renderProposals()+'<p class="small">Propostas · catálogo e condições independentes por empresa</p>';};
